html:
{%- import "costeo_yelke/templates/print/oc_yelke.html" as oc -%}
{#- Orden de venta. Diseño: templates/print/oc_yelke.html -#}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, "Orden de venta") }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}
{{ oc.datos(doc, {"etiqueta": "Cliente", "nombre": doc.customer_name or doc.customer, "rfc": rfc_tercero("Customer", doc.customer), "direccion": direccion_lineas(doc.customer_address)},
    [("Fecha de elaboración", fecha_corta(doc.transaction_date)),
     ("Entrega acordada", fecha_corta(doc.delivery_date)),
     ("Cotización", (doc.items[0].prevdoc_docname if doc.items else None)),
     ("OC del cliente", doc.get("po_no")),
     ("Moneda", doc.currency)]) }}
{{ oc.tabla_articulos(doc) }}
{{ oc.cierre(doc) }}
</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
